import { test, expect } from '@playwright/test';

test.describe('Video Player Responsiveness', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
    await page.setViewportSize({ width: 768, height: 1024 }); // Tablet viewport size
  });

  test('should resize video player proportionally', async ({ page }) => {
    const videoPlayer = page.getByRole('video');
    const initialWidth = await videoPlayer.evaluate(el => el.clientWidth);
    const initialHeight = await videoPlayer.evaluate(el => el.clientHeight);

    await page.setViewportSize({ width: 1024, height: 768 }); // Change to a different tablet size
    await page.waitForTimeout(1000); // Wait for resize to take effect

    const newWidth = await videoPlayer.evaluate(el => el.clientWidth);
    const newHeight = await videoPlayer.evaluate(el => el.clientHeight);

    expect(newWidth / newHeight).toBeCloseTo(initialWidth / initialHeight, 2);
  });

  test('should maintain aspect ratio on orientation change', async ({ page }) => {
    const videoPlayer = page.getByRole('video');
    const initialWidth = await videoPlayer.evaluate(el => el.clientWidth);
    const initialHeight = await videoPlayer.evaluate(el => el.clientHeight);

    await page.setViewportSize({ width: 768, height: 1024 }); // Portrait orientation
    await page.waitForTimeout(1000); // Wait for resize to take effect

    const portraitWidth = await videoPlayer.evaluate(el => el.clientWidth);
    const portraitHeight = await videoPlayer.evaluate(el => el.clientHeight);

    expect(portraitWidth / portraitHeight).toBeCloseTo(initialWidth / initialHeight, 2);
  });
});
